from collections import Counter
from pathlib import Path
import re
import sys
import unicodedata

import fitz


work = Path(__file__).parent
first = Path("output/27302阶段模拟卷.tex")
remaining = Path("output/27302阶段模拟卷（第二至五卷及补充练习）.tex")
groups = [f"第{number}卷" for number in "一二三四五"] + ["补充练习"]
counts = [22] * 5 + [76]
page_titles = []

preamble = r"""
\documentclass[UTF8,zihao=-3,fontset=fandol]{ctexart}
\usepackage[paperwidth=800bp,paperheight=600bp,left=44bp,right=44bp,top=38bp,bottom=38bp]{geometry}
\usepackage{amsmath,amssymb,enumitem,tabularx,xcolor}
\usepackage[hidelinks,pdfpagelayout=SinglePage,pdfstartview=Fit]{hyperref}
\hypersetup{pdftitle={27302 高等数学阶段模拟卷（iPad 横屏版）}}
\pagestyle{empty}
\raggedbottom
\setlength{\parindent}{0pt}
\setlength{\tabcolsep}{0pt}
\setlist[enumerate]{label=(\arabic*),leftmargin=2em,topsep=.4em,itemsep=.3em}
\newcommand{\blank}{\underline{\hspace{3em}}}
\newcommand{\choices}[4]{%
  \par\vspace{0.4em}
  \noindent\begin{tabularx}{\linewidth}{@{}X@{\hspace{1.5em}}X@{}}
    (A)\,#1 & (B)\,#2 \\
    (C)\,#3 & (D)\,#4
  \end{tabularx}\par}
\newcommand{\questionheading}[1]{%
  {\fontsize{11bp}{15bp}\selectfont\color[gray]{0.35}#1\par}%
  \vspace{6bp}%
  {\color[gray]{0.80}\hrule height 0.4bp}%
  \vspace{12bp}}
\begin{document}
"""


def extract(source):
    questions = []
    depth = 0
    number = 0
    item = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith(r"\begin{enumerate}"):
            if depth == 0:
                start = re.search(r"\bstart=(\d+)", stripped)
                number = int(start[1]) - 1 if start else 0
            else:
                item.append(line)
            depth += 1
        elif stripped == r"\end{enumerate}":
            depth -= 1
            assert depth >= 0
            if depth == 0:
                assert item
                questions.append((number, "\n".join(item).strip()))
                item = []
            else:
                item.append(line)
        elif depth == 1 and stripped.startswith(r"\item "):
            if item:
                questions.append((number, "\n".join(item).strip()))
            number += 1
            item = [stripped.removeprefix(r"\item ")]
        elif item and not stripped.startswith(("%", r"\vspace{")):
            item.append(line)
    assert depth == 0 and not item
    return questions


def prepare():
    main = first.read_text().split(r"\begin{document}", 1)[1]
    added = remaining.read_text().split(r"\begin{document}", 1)[1]
    papers, extra = added.split(r"\pdfbookmark[0]{补充练习}{extra}", 1)
    sources = [main, *re.split(r"\\paper\{[二三四五]\}", papers)[1:], extra]
    pages = []
    assert len(sources) == len(groups)
    for group_index, (group, count, source) in enumerate(zip(groups, counts, sources)):
        questions = extract(source)
        assert [number for number, _ in questions] == list(range(1, count + 1)), group
        last_choice, last_fill = (21, 49) if group == groups[-1] else (10, 16)
        for number, stem in questions:
            kind = "选择题" if number <= last_choice else "填空题" if number <= last_fill else "解答题"
            assert stem.count(r"\choices") == (kind == "选择题"), (group, number)
            assert (r"\blank" in stem) == (kind == "填空题"), (group, number)
            heading = f"{group} · 第 {number} 题 · {kind}"
            if group != groups[-1]:
                score = 5 if number <= 16 else 10 if number == 17 else 12
                heading += f" · {score} 分"
                if number > 16:
                    prefix = rf"\textbf{{（{score} 分）}} "
                    assert stem.startswith(prefix), (group, number)
                    stem = stem.removeprefix(prefix)
            bookmark = rf"\pdfbookmark[0]{{{group}}}{{group-{group_index}}}" if number == 1 else ""
            pages.append(bookmark + "\n" + rf"\questionheading{{{heading}}}" + "\n" + stem)
            page_titles.append(heading)
    return preamble + "\n\\newpage\n".join(pages) + "\n\\end{document}\n"


def normalized(text):
    return re.sub(r"\s+", "", unicodedata.normalize("NFKC", text))


def original_questions(source, page_ranges):
    with fitz.open(source) as doc:
        for first_page, end_page, count in page_ranges:
            questions = []
            for page in doc.pages(first_page, end_page):
                lines = page.get_text().splitlines()
                assert lines.pop(0).strip() == str(page.number + 1)
                for line in lines:
                    if re.match(r"^(?:27302 |《工科|第一章至|满分|建议用时|[一二三]、|第\d)", line):
                        continue
                    start = re.match(r"^(\d+)\.\s*(?:（\d+ 分）\s*)?(.*)$", line)
                    if start and int(start[1]) == len(questions) + 1:
                        questions.append(start[2])
                    elif questions:
                        questions[-1] += "\n" + line
                    else:
                        raise ValueError(f"Unrecognized original text: {line!r}")
            assert len(questions) == count, (source, first_page, len(questions))
            yield from questions


def verify():
    originals = list(original_questions(first.with_suffix(".pdf"), [(0, 4, 22)]))
    ranges = [(page, page + 4, 22) for page in range(0, 16, 4)] + [(16, 22, 76)]
    originals.extend(original_questions(remaining.with_suffix(".pdf"), ranges))
    lowest = 0
    differences = []
    with fitz.open(work / "combined.pdf") as doc:
        assert len(doc) == len(originals) == len(page_titles) == 186
        assert doc.get_toc() == [[1, group, 1 + 22 * index] for index, group in enumerate(groups)]
        for page, title, original in zip(doc, page_titles, originals):
            assert page.rect == fitz.Rect(0, 0, 800, 600)
            assert page.mediabox == page.rect and page.rotation == 0
            header, body = page.get_text().split("\n", 1)
            assert normalized(header) == normalized(title), (page.number + 1, header, title)
            assert body.strip() and "\ufffd" not in body and not page.get_images()
            expected, actual = Counter(normalized(original)), Counter(normalized(body))
            if expected != actual:
                differences.append((page.number + 1, title, expected - actual, actual - expected))
            for _, bounds in page.get_bboxlog():
                left, top, right, bottom = bounds
                assert 38 <= left < right <= 762 and 30 <= top < bottom <= 300, (title, bounds)
                lowest = max(lowest, bottom)
    assert not differences, differences
    print(f"186 pages, six bookmarks, 800 × 600 pt, at least {600 - lowest:.1f} pt of blank space.")


tex = prepare()
if sys.argv[1:] == ["verify"]:
    verify()
else:
    assert not sys.argv[1:]
    (work / "combined.tex").write_text(tex)

