from pathlib import Path
import re
import sys

import fitz


work = Path(__file__).parent
source = Path("output/pdf/27302阶段模拟卷（iPad横屏版）.pdf")
preamble = r"""
\documentclass[UTF8,zihao=-4,fontset=fandol]{ctexart}
\usepackage[paperwidth=800bp,paperheight=600bp,left=44bp,right=44bp,top=38bp,bottom=37bp]{geometry}
\usepackage{amsmath,amssymb,xcolor}
\definecolor{heading}{gray}{0.35}
\definecolor{accent}{HTML}{234661}
\pagestyle{empty}
\raggedbottom
\setlength{\parindent}{0pt}
\setlength{\parskip}{.55em}
\renewcommand{\baselinestretch}{1.16}
\newcommand{\solutionpage}[1]{%
  {\fontsize{11bp}{15bp}\selectfont\color{heading}#1\par}%
  \vspace{2bp}%
  {\color[gray]{0.80}\hrule height 0.4bp}%
  \vspace{8bp}}
\newcommand{\approach}[1]{%
  \textcolor{accent}{\textbf{入手角度}}\quad #1\par
  \textcolor{accent}{\textbf{推导}}\par}
\newcommand{\answer}[1]{\par\textcolor{accent}{\textbf{答案}}\quad #1\par}
\begin{document}
"""


def normalize(text):
    return re.sub(r"\s+", "", text)


def load(group, path, numbers):
    text = (work / path).read_text()
    parts = re.split(r"(?m)^\\solution\{(\d+)\}[ \t]*\n", text)
    assert not parts[0].strip() and list(map(int, parts[1::2])) == list(numbers), path
    for number, body in zip(numbers, parts[2::2]):
        assert body.startswith(r"\approach{") and body.count(r"\approach{") == 1, (path, number)
        assert len(body.splitlines()) >= 2 and "TODO" not in body, (path, number)
        assert not re.search(r"\\(?:newpage|pagebreak|clearpage|include|input)\b", body)
        yield (f"{group} · 第 {number} 题", body.strip())


solutions = []
for index, ordinal in enumerate("一二三四五", start=1):
    solutions.extend(load(f"第{ordinal}卷", f"paper{index}.tex", range(1, 23)))
solutions.extend(load("补充练习", "extra1.tex", range(1, 50)))
solutions.extend(load("补充练习", "extra2.tex", range(50, 77)))
assert len(solutions) == 186


def prepare():
    pages = [rf"\solutionpage{{{title}解析}}" + "\n" + body for title, body in solutions]
    (work / "solutions.tex").write_text(preamble + "\n\\newpage\n".join(pages) + "\n\\end{document}\n")


def validate_answers(solved):
    assert len(solved) == len(solutions)
    expected_rect = fitz.Rect(0, 0, 800, 600)
    for page, (title, body) in zip(solved, solutions):
        text = page.get_text()
        heading = text.splitlines()[0]
        assert normalize(heading) == normalize(title + "解析"), (page.number + 1, heading, title)
        assert page.rect == expected_rect and page.mediabox == expected_rect and page.rotation == 0
        assert text.count("入手角度") == text.count("推导") == 1 and "\ufffd" not in text, title
        assert len(text) > 65, (title, text)
        if r"\answer{" in body:
            assert "答案" in text
        assert not page.get_images()
        for _, (left, top, right, bottom) in page.get_bboxlog():
            assert 35 <= left < right <= 766 and 30 <= top < bottom <= 570, (
                title, left, top, right, bottom
            )


def verify(original, combined, solved, toc):
    assert len(combined) == 372 and combined.pagelayout == "SinglePage"
    assert combined.get_toc() == toc
    assert [entry[2] for entry in toc] == [1, 45, 89, 133, 177, 221]
    for index, (title, _) in enumerate(solutions):
        prior, question, explanation = original[index], combined[2 * index], combined[2 * index + 1]
        assert question.rect == explanation.rect == prior.rect == fitz.Rect(0, 0, 800, 600)
        assert normalize(question.get_text().splitlines()[0]).startswith(normalize(title) + "·"), title
        assert question.get_text("rawdict") == prior.get_text("rawdict"), title
        assert question.get_bboxlog() == prior.get_bboxlog(), title
        assert max(bounds[-1] for _, bounds in question.get_bboxlog()) <= 225.1, title
        assert explanation.get_text("rawdict") == solved[index].get_text("rawdict"), title
        assert explanation.get_bboxlog() == solved[index].get_bboxlog(), title


def assemble():
    output = work / "verified.pdf"
    with fitz.open(source) as original, fitz.open(work / "solutions.pdf") as solved:
        assert len(original) == len(solutions)
        validate_answers(solved)
        toc = [[level, title, 2 * page - 1] for level, title, page in original.get_toc()]
        with fitz.open() as combined:
            for index in range(len(original)):
                last = int(index == len(original) - 1)
                combined.insert_pdf(original, from_page=index, to_page=index, final=last)
                combined.insert_pdf(solved, from_page=index, to_page=index, final=last)
            combined.set_metadata({
                "title": "27302 高等数学阶段模拟卷（iPad 横屏版）",
                "subject": "第一至五卷及补充练习，附逐题解析",
            })
            combined.set_pagelayout("SinglePage")
            combined.set_toc(toc)
            combined.save(output, garbage=4, deflate=True)
        with fitz.open(output) as combined:
            verify(original, combined, solved, toc)
    print("186 question pages preserved, 186 consecutive solution pages, 372 pages at 800 × 600 pt, six verified bookmarks.")


if sys.argv[1:] == ["assemble"]:
    assemble()
else:
    assert not sys.argv[1:]
    prepare()

